style.css:
@-moz-document domain("youtube.com") {
/* Fondo general de YouTube */
    body {
        background: linear-gradient(to bottom, #1b3b2f, #2e2a26); /* Fondo bosque oscuro */
        color: #ffffff; /* Texto blanco */
    }

    /* Barra superior (header) */
    #container.ytd-masthead, #masthead-container {
        background-color: #283a3b !important; /* Verde militar */
        color: #e6f1ff !important; /* Azul claro */
    }

    /* Texto en la barra de búsqueda */
    #search-input input {
        background-color: #2b4737 !important; /* Verde oscuro */
        color: #e6f1ff !important; /* Azul claro */
        border: 1px solid #4fb3ff !important; /* Azul espada */
    }

    /* Botón de búsqueda */
    #search-icon-legacy {
        color: #00ffff !important; /* Cian brillante */
        background-color: #2b4737 !important;
        border-radius: 5px;
        padding: 5px;
    }

    /* Miniaturas de videos */
    ytd-thumbnail {
        border: 2px solid #4fb3ff !important; /* Azul espada */
        border-radius: 10px;
    }

    /* Títulos de videos */
    a#video-title {
        color: #e6f1ff !important; /* Azul claro */
        text-shadow: 0 0 5px #00ffff; /* Resplandor */
    }

    a#video-title:hover {
        color: #00ffff !important; /* Azul espada */
    }

    /* Fondo de los botones (like, share, etc.) */
    ytd-menu-renderer {
        background-color: #2b4737 !important; /* Verde oscuro */
        border-radius: 10px;
    }

    /* Cambiar el estilo del botón de suscripción */
    tp-yt-paper-button.ytd-subscribe-button-renderer {
        background-color: #4fb3ff !important; /* Azul espada */
        color: #000000 !important; /* Texto negro */
        border-radius: 5px;
        padding: 5px 15px;
    }

    tp-yt-paper-button.ytd-subscribe-button-renderer:hover {
        background-color: #00ffff !important; /* Cian brillante */
        color: #000000 !important;
        box-shadow: 0 0 10px #00ffff; /* Resplandor */
    }

    /* Fondo de los comentarios */
    #contents.ytd-item-section-renderer {
        background-color: #1b3b2f !important; /* Verde oscuro */
        border-radius: 10px;
        padding: 10px;
    }

    /* Texto de los comentarios */
    yt-formatted-string.ytd-comment-renderer {
        color: #e6f1ff !important; /* Azul claro */
    }

    /* Cambiar el footer */
    ytd-footer-renderer {
        background-color: #283a3b !important; /* Verde militar */
        color: #e6f1ff !important;
        text-align: center;
        padding: 20px;
    }
}
